import pandas as pd
import numpy as np
from typing import dict

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    target_state = inputs["target_state"].copy()
    cdc_events = inputs["cdc_events"].copy()

    # Ensure proper types
    target_state["order_id"] = target_state["order_id"].astype("int64")
    target_state["last_seq"] = target_state["last_seq"].astype("int64")
    cdc_events["seq"] = cdc_events["seq"].astype("int64")
    cdc_events["order_id"] = cdc_events["order_id"].astype("int64")

    # Step 1: Remove duplicate events (same seq) - keep first occurrence
    cdc_events = cdc_events.drop_duplicates(subset=["seq"], keep="first")

    # Step 2: Apply replay guard - filter out events where seq <= last_seq for existing orders
    # Create a dict of order_id -> last_seq from target_state for quick lookup
    last_seq_map = dict(zip(target_state["order_id"], target_state["last_seq"]))

    # Mark events to skip based on replay guard
    def should_skip(row):
        order_id = row["order_id"]
        seq = row["seq"]
        if order_id in last_seq_map:
            return seq <= last_seq_map[order_id]
        return False

    cdc_events["skip"] = cdc_events.apply(should_skip, axis=1)
    cdc_events = cdc_events[~cdc_events["skip"]].drop(columns=["skip"])

    # Step 3: Sort events by seq (order of application)
    cdc_events = cdc_events.sort_values(by=["seq"]).reset_index(drop=True)

    # Step 4: Build state dict for in-memory processing
    # state_dict: order_id -> {status, amount, last_seq, last_op}
    state_dict = {}
    for _, row in target_state.iterrows():
        order_id = row["order_id"]
        state_dict[order_id] = {
            "status": row["status"],
            "amount": row["amount"],
            "last_seq": row["last_seq"],
            "last_op": None  # Track last op for tombstone detection
        }

    # Step 5: Apply events in sequence order
    for _, event in cdc_events.iterrows():
        order_id = event["order_id"]
        seq = event["seq"]
        op = event["op"]
        status = event["status"]
        amount = event["amount"]

        if op in ("I", "U"):
            if order_id not in state_dict:
                # Create new row
                state_dict[order_id] = {
                    "status": status,
                    "amount": amount,
                    "last_seq": seq,
                    "last_op": op
                }
            else:
                # Update existing row
                state_dict[order_id]["status"] = status
                # For 'U', preserve amount if event amount is NULL
                if op == "U" and pd.isna(amount):
                    # Leave amount unchanged
                    pass
                else:
                    state_dict[order_id]["amount"] = amount
                state_dict[order_id]["last_seq"] = seq
                state_dict[order_id]["last_op"] = op
        elif op == "D":
            if order_id in state_dict:
                # Mark as deleted (keep the row temporarily to track last_op)
                state_dict[order_id]["last_op"] = "D"
                state_dict[order_id]["last_seq"] = seq
                # Actually remove it from state
                del state_dict[order_id]

    # Step 6: Build new_state from state_dict
    new_state_rows = []
    for order_id, state in state_dict.items():
        new_state_rows.append({
            "order_id": order_id,
            "status": state["status"],
            "amount": state["amount"],
            "last_seq": state["last_seq"]
        })

    if new_state_rows:
        new_state = pd.DataFrame(new_state_rows)
    else:
        new_state = pd.DataFrame(columns=["order_id", "status", "amount", "last_seq"])

    # Step 7: Build tombstones - orders that had a row and whose last applied event was 'D'
    # We need to track which orders ever existed and had a final 'D' operation
    tombstone_rows = []

    # Build a tracking dict: order_id -> final state including last_op
    final_state_tracker = {}

    # Start with target_state orders
    for _, row in target_state.iterrows():
        order_id = row["order_id"]
        final_state_tracker[order_id] = {
            "last_op": None,
            "last_seq": row["last_seq"]
        }

    # Process events again to track final operations
    cdc_events_sorted = inputs["cdc_events"].drop_duplicates(subset=["seq"], keep="first").sort_values(by=["seq"])

    for _, event in cdc_events_sorted.iterrows():
        order_id = event["order_id"]
        seq = event["seq"]
        op = event["op"]

        # Check replay guard
        if order_id in last_seq_map and seq <= last_seq_map[order_id]:
            continue

        if order_id not in final_state_tracker:
            final_state_tracker[order_id] = {}

        final_state_tracker[order_id]["last_op"] = op
        final_state_tracker[order_id]["last_seq"] = seq

    # Create tombstones for orders with final 'D' operation
    for order_id, state in final_state_tracker.items():
        if state.get("last_op") == "D":
            tombstone_rows.append({
                "order_id": order_id,
                "deleted_seq": state["last_seq"]
            })

    if tombstone_rows:
        tombstones = pd.DataFrame(tombstone_rows)
    else:
        tombstones = pd.DataFrame(columns=["order_id", "deleted_seq"])

    # Ensure correct dtypes
    if not new_state.empty:
        new_state["order_id"] = new_state["order_id"].astype("int64")
        new_state["status"] = new_state["status"].astype("object")
        new_state["amount"] = new_state["amount"].astype("float64")
        new_state["last_seq"] = new_state["last_seq"].astype("int64")
    else:
        new_state = new_state.astype({
            "order_id": "int64",
            "status": "object",
            "amount": "float64",
            "last_seq": "int64"
        })

    if not tombstones.empty:
        tombstones["order_id"] = tombstones["order_id"].astype("int64")
        tombstones["deleted_seq"] = tombstones["deleted_seq"].astype("int64")
    else:
        tombstones = tombstones.astype({
            "order_id": "int64",
            "deleted_seq": "int64"
        })

    return {
        "new_state": new_state,
        "tombstones": tombstones
    }
